import * as stream from 'node:stream';
function main(): void {
  const s: any = stream;
  console.log(typeof s.Readable.wrap, typeof s.Readable.ReadableState, typeof s.Writable.WritableState);
  const w: any = new s.Readable.ReadableState({ objectMode: true });
  console.log(Object.keys(w), w.highWaterMark);
  const src: any = s.Readable.from(['a', 'b']);
  const wrapped: any = s.Readable.wrap(src);
  const out: string[] = [];
  wrapped.on('data', (c: any) => out.push(String(c)));
  wrapped.on('end', () => console.log(out.join(',')));
}
